<script setup lang="ts">
import AppLayout from '@/layouts/AppLayout.vue';
import { Head, useForm } from '@inertiajs/vue3';
import { computed } from 'vue';
const props = defineProps<{ terms: any[]; activeTerm: any; classes: any[]; enrollments: any[]; events: any[] }>();
const form = useForm({ enrollment_id: '', action: 'promoted', target_term_id: '', target_class_group_id: '', effective_date: new Date().toISOString().slice(0,10), notes: '' });
const requiresTarget = computed(() => ['promoted','retained'].includes(form.action));
const targetClasses = computed(() => { const term = props.terms.find(t => String(t.id) === String(form.target_term_id)); return term ? props.classes.filter(c => c.academic_year_id === term.academic_year_id) : []; });
const submit = () => form.post('/akademik/siklus-siswa', { onSuccess: () => form.reset('enrollment_id','target_term_id','target_class_group_id','notes') });
const labels: Record<string,string> = { promoted:'Naik kelas', retained:'Tinggal kelas', graduated:'Lulus', withdrawn:'Keluar' };
</script>
<template><Head title="Siklus Siswa"/><AppLayout><div class="page-heading"><div><p class="eyebrow">Administrasi akademik</p><h1>Siklus siswa</h1><p>Proses kenaikan, tinggal kelas, kelulusan, dan keluar tanpa menghapus histori enrollment.</p></div></div><div class="content-grid two-columns"><form class="card card-body" @submit.prevent="submit"><h2>Proses siswa</h2><div class="form-grid"><label class="field span-2">Siswa aktif<select v-model="form.enrollment_id" required><option value="">Pilih siswa</option><option v-for="e in enrollments" :key="e.id" :value="e.id">{{ e.student?.nis }} — {{ e.student?.name }} ({{ e.class_group?.name }})</option></select></label><label class="field">Keputusan<select v-model="form.action"><option value="promoted">Naik kelas</option><option value="retained">Tinggal kelas</option><option value="graduated">Lulus</option><option value="withdrawn">Keluar</option></select></label><label class="field">Tanggal efektif<input v-model="form.effective_date" type="date" required></label><label v-if="requiresTarget" class="field">Periode tujuan<select v-model="form.target_term_id" required><option value="">Pilih periode</option><option v-for="t in terms" :key="t.id" :value="t.id">{{ t.academic_year?.name }} — {{ t.name }}</option></select></label><label v-if="requiresTarget" class="field">Kelas tujuan<select v-model="form.target_class_group_id" required><option value="">Pilih kelas</option><option v-for="c in targetClasses" :key="c.id" :value="c.id">{{ c.name }} (tingkat {{ c.grade_level }})</option></select></label><label class="field span-2">Catatan<textarea v-model="form.notes" rows="3"></textarea></label></div><p v-if="form.errors.action" class="form-error">{{ form.errors.action }}</p><div class="form-actions"><button class="btn btn-primary" :disabled="form.processing">Proses keputusan</button></div></form><div class="card card-body"><h2>Ketentuan</h2><p>Naik dan tinggal kelas membuat enrollment baru pada periode tujuan. Lulus dan keluar menutup enrollment aktif. Setiap keputusan tersimpan di audit dan ledger siklus siswa.</p></div></div><div class="card overflow-hidden"><table class="data-table"><thead><tr><th>Tanggal</th><th>Siswa</th><th>Keputusan</th><th>Perpindahan</th><th>Catatan</th></tr></thead><tbody><tr v-for="e in events" :key="e.id"><td>{{ new Date(e.effective_date).toLocaleDateString('id-ID') }}</td><td><strong>{{ e.student?.name }}</strong><br>{{ e.student?.nis }}</td><td>{{ labels[e.action] }}</td><td>{{ e.source_enrollment?.class_group?.name ?? '—' }} → {{ e.target_enrollment?.class_group?.name ?? '—' }}</td><td>{{ e.notes || '—' }}</td></tr><tr v-if="!events.length"><td colspan="5" class="empty-state">Belum ada keputusan siklus siswa.</td></tr></tbody></table></div></AppLayout></template>
